#pragma config(Motor, port1, testMotor, tmotorVex393_HBridge, openLoop)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

/*
ENGR 10 Week 1 - Practice program 1
Gradually increases the motor speed from 0 to maximum (127) in about 10 seconds.
128 steps x 78 ms = about 10 seconds.
*/
task main()
{
	int speed = 0;

	while(speed <= 127)
	{
		motor[testMotor] = speed;
		wait1Msec(78);
		speed = speed + 1;
	}

	wait1Msec(3000);         // stay at maximum speed for 3 seconds so you can see it
	motor[testMotor] = 0;
}
